import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Calidad de objetos / Obras maestras","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/items/item-quality.md","filePath":"es/guide/items/item-quality.md"}'),r={name:"es/guide/items/item-quality.md"};function s(n,a,d,l,c,u){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="item-quality-masterworks" tabindex="-1">Calidad de objetos / Obras maestras <a class="header-anchor" href="#item-quality-masterworks" aria-label="Enlace permanente a &quot;Calidad de objetos / Obras maestras&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>La calidad significa cumplir bien la función del objeto: <a href="/Syrolands-Public/es/guide/glossary.html#handling">manejo</a>, <a href="/Syrolands-Public/es/guide/glossary.html#consistency">consistencia</a>, integridad y conservación del rendimiento.</li><li>La <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a>, las <a href="/Syrolands-Public/es/guide/characters/techniques.html">técnicas</a>, los materiales y la ejecución definen los resultados; el azar tiene un papel pequeño.</li><li>Una <a href="/Syrolands-Public/es/guide/glossary.html#masterwork">obra maestra</a> no es automáticamente mágica y el equipo excelente puede perderse.</li></ul><p><span id="quality-means-doing-a-job-well"></span><span id="the-proposed-categories"></span><span id="what-you-might-notice"></span><span id="special-properties-and-memorable-items"></span><span id="related-systems"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Calidad compartida</td><td>El equipo fabricado y el botín de monstruos usan un lenguaje de calidad compatible.</td></tr><tr><td>Identidad del arma</td><td>La calidad mejora la función propia del arma; una daga de calidad no se convierte en un martillo de guerra.</td></tr><tr><td>Masterwork (obra maestra)</td><td>Una obra maestra técnica extremadamente rara, no un resultado habitual con habilidad 100.</td></tr><tr><td><a href="/Syrolands-Public/es/guide/glossary.html#latent-property">Latent Property</a> (propiedad latente)</td><td>Una resonancia inactiva rara podría despertar mediante un uso excepcional, un lugar, una criatura o un ritual.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>El equipo excepcional fabricado ya recompensa la artesanía.</td><td>La calidad también destaca el manejo, la consistencia y la conservación del rendimiento.</td></tr><tr><td>Las propiedades mágicas y la calidad artesanal son ideas conocidas del equipo.</td><td>Los rasgos raros necesitan justificación y compromisos; la excelencia técnica no garantiza magia.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/blacksmithing/" target="_blank" rel="noreferrer">Blacksmithing</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Una espada larga Exceptional podría tener mejor equilibrio y conservar el filo más tiempo que una Common, mientras la espada Common sigue siendo útil. Un arco de Frostwood que despierta tras un suceso relacionado con el frío es solo un ejemplo, no una receta garantizada.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>Crude, Common, Fine, Exceptional y Superior describen una calidad artesanal progresivamente mayor. Masterwork sigue siendo raro; Singular / Relic describe una historia o conducta inusual, no un siguiente nivel rutinario.</li><li>El equipo excelente ordinario debe seguir siendo competitivo. Los rasgos, las condiciones de despertar y los futuros conjuntos resonantes siguen sin decidirse; ninguno concede seguro ni protección frente al saqueo.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a> · <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Herrería</a> · <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpintería / Fabricación de arcos</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">Calidad de objetos / Obras maestras</a></p>',18)])])}const h=e(r,[["render",s]]);export{p as __pageData,h as default};
